import * as R from './raids.js?v=13.0.0';
import * as M from './model.js?v=13.0.0';
import {escapeHtml as esc} from './features.js?v=13.0.0';
const n=v=>Math.floor(v||0).toLocaleString('en-US');
const icon=id=>`<i data-lucide="${id}"></i>`;
const button=(label,action,extra='')=>`<button class="btn btn-gold" data-raid="${action}" ${extra}>${label}</button>`;
const duration=ms=>ms<=0?'No Shield':ms>3600000?Math.ceil(ms/3600000)+'h':Math.ceil(ms/60000)+'m';

export class RaidUI {
  constructor(bridge){this.b=bridge;this.tab='all';this.busy=false;
    bridge.features.raids=()=>this.history();
    document.addEventListener('click',e=>{const el=e.target.closest('[data-raid]');if(el&&!el.disabled)this.handle(el).catch(err=>bridge.toast(err.message,true));});
  }
  show(kind,title,body){this.b.showModal('raid-'+kind,this.b.header('KINGDOMS AT WAR',title)+`<div class="modal-body">${body}</div>`);}
  menu(){const s=this.b.root(),ready=M.armySize(s.army)>0||Object.values(s.heroes).some(h=>h.level&&!h.finishAt&&!(h.recoverAt>Date.now()));
    this.show('menu','Choose your battle',`<div class="raid-choice"><div><span class="eyebrow">TOWN HALL ${M.hallLevel(s)}</span><h3>Find a rival village</h3><p>${this.b.api.online?'Find a random player near your Town Hall level. If none is available, raid a matching AI village.':'Raid a random AI village matched to your Town Hall level.'}</p>${button(icon('swords')+' Find a match','find',ready?'':'disabled')}<small>${s.shieldUntil>Date.now()?'Deploying troops removes your active Shield.':'Scout freely. Your troops are spent only when deployed.'}</small></div><div class="loot-rule"><strong>10%</strong><span>Maximum available loot</span><p>Gold · Elixir · Dark Elixir</p></div></div><p class="modal-intro">A complete victory can take 10% of the defender’s stored balance. Partial destruction earns a proportional share. Gems cannot be stolen.</p><div class="raid-menu-actions">${button(icon('history')+' Attack & defense log','history')}${button(icon('shield')+' Shield shop','shields')}${button(icon('map')+' Campaign','campaign')}</div>${!ready?'<p class="shop-status">Train troops or unlock a ready hero before searching.</p>':''}`);
  }
  async history(tab=this.tab){this.tab=tab;const rows=this.b.api.online?(await this.b.api.request('/raids')).raids:(this.b.root().raids?.history||[]);const selected=rows.filter(r=>tab==='all'||r.direction===tab);
    this.show('history','Attack & defense history',`<div class="expansion-tabs">${[['all','All battles'],['attack','Your attacks'],['defense','Your defenses']].map(([id,label])=>`<button class="btn ${id===tab?'btn-gold':''}" data-raid="history" data-tab="${id}" aria-pressed="${id===tab}">${label}</button>`).join('')}</div><div class="raid-history">${selected.map(r=>{const a=r.direction==='attack',result=r.result;return `<article class="raid-record ${a?'raid-record-attack':'raid-record-defense'}"><span class="raid-record-icon">${icon(a?'swords':'shield')}</span><div><small>${a?'YOUR ATTACK':'YOUR DEFENSE'} · ${r.opponentType==='bot'?'AI':'PLAYER'}${r.hall?' · TH '+r.hall:''}</small><h3>${esc(r.opponent)}</h3><p>${result.percent}% destruction · <span class="log-stars">${'★'.repeat(result.stars||0)}${'☆'.repeat(3-(result.stars||0))}</span></p><time>${esc(new Date(r.created_at).toLocaleString())}</time></div><div class="log-loot"><strong>${a?'Loot gained':'Resources lost'}</strong><span>${icon('coins')}${a?'+':'−'}${n(result.gold)}</span><span>${icon('droplets')}${a?'+':'−'}${n(result.elixir)}</span><span>${icon('fuel')}${a?'+':'−'}${n(result.dark)}</span></div></article>`;}).join('')||'<p class="empty-log">No '+(tab==='all'?'battles':tab==='attack'?'attacks':'defenses')+' yet. Your completed battles will appear here.</p>'}</div><p class="guide-foot">When no active rival is available, an AI army can raid an unshielded village after 6 hours. There is at most one catch-up raid when you return.</p>`);
  }
  shields(){const s=this.b.root();this.show('shields','Protect your village',`<div class="shield-current">${icon('shield-check')}<div><strong>${s.shieldUntil>Date.now()?'Shield active · '+duration(s.shieldUntil-Date.now()):'Your village is unshielded'}</strong><p>${s.shieldUntil>Date.now()?'Protected until '+esc(new Date(s.shieldUntil).toLocaleString()):'Players and AI raiders can attack your village.'}</p></div></div><p class="wallet-total">${icon('gem')} ${n(s.gems)} <span>gems</span></p><div class="card-grid">${R.SHIELDS.map(p=>`<article class="shop-card"><span class="card-icon">${icon('shield')}</span><h3>${p.name}</h3><p>Protects against player and AI raids.</p>${button(icon('gem')+' '+p.gems+' · Buy Shield','buy-shield',`data-id="${p.id}" ${s.gems<p.gems?'disabled':''}`)}</article>`).join('')}</div><p class="guide-foot">Up to 7 days can be stacked. Deploying an army in a rival raid removes your Shield. Scouting and campaign battles preserve it. A completed incoming attack grants 5 minutes of protection.</p>`);}
  tick(){const s=this.b.root(),battle=this.b.battle(),shield=document.getElementById('shield-status');const shieldText=duration((s.shieldUntil||0)-Date.now());if(shield&&this.shieldSignature!==shieldText){this.shieldSignature=shieldText;shield.innerHTML=icon(s.shieldUntil>Date.now()?'shield-check':'shield')+' '+duration((s.shieldUntil||0)-Date.now());shield.classList.toggle('protected',s.shieldUntil>Date.now());window.lucide?.createIcons();}
    const scout=document.getElementById('raid-scout');scout.hidden=!battle?.raid;
    if(battle?.raid){const signature=JSON.stringify([battle.id,battle.started,battle.ended]);if(signature!==this.scoutSignature){this.scoutSignature=signature;scout.innerHTML=`<small>${battle.enemy.kind==='bot'?'AI VILLAGE':'PLAYER VILLAGE'} · TH ${battle.enemy.hall}</small><strong>Available loot · 10%</strong><div class="scout-resources"><span>${icon('coins')}${n(battle.enemy.gold)}</span><span>${icon('droplets')}${n(battle.enemy.elixir)}</span><span>${icon('fuel')}${n(battle.enemy.dark)}</span></div>${!battle.started&&!battle.ended?button('Next village '+icon('arrow-right'),'next'):'<small>Loot follows destruction</small>'}`;window.lucide?.createIcons();}}
  }
  async handle(el){if(this.busy)return;const a=el.dataset.raid;this.busy=true;el.disabled=true;try{
    if(a==='find')await this.b.startBattle(0,null,{mode:'match'});
    else if(a==='next'){if(this.b.battle()?.started)return;await this.b.home();await this.b.startBattle(0,null,{mode:'match'});}
    else if(a==='menu')this.menu();else if(a==='campaign')this.b.campaign();
    else if(a==='history')await this.history(el.dataset.tab||'all');else if(a==='shields')this.shields();
    else if(a==='buy-shield'){await this.b.mutate({type:'shield-buy',shield:el.dataset.id});this.b.toast('Shield activated.');this.shields();}
    else if(a==='gem-box'){const box=this.b.root().obstacles.find(o=>o.type==='gem-box');if(box)this.b.features.obstacle(box.id);else this.b.toast('Next Gem Box: '+new Date(this.b.root().nextGemBoxAt).toLocaleString());}
  }finally{this.busy=false;if(el.isConnected)el.disabled=false;}}
}
